-- Separate open-reference records from 2026 workbook; NEVER conflate with modeled unit entries.
CREATE SCHEMA refdata;
CREATE TABLE refdata.reference_entry (entry_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_file TEXT NOT NULL, source_sheet TEXT NOT NULL, source_row INTEGER NOT NULL, record_kind TEXT NOT NULL CHECK(record_kind IN ('position_publication','personnel_reference','item_norm_reference')), raw_fields JSONB NOT NULL, verified_for_operational_use BOOLEAN NOT NULL DEFAULT FALSE, imported_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_file, source_sheet, source_row));
COMMENT ON TABLE refdata.reference_entry IS 'Справочные строки из пользовательского Excel. Не подтверждённый текущий штат конкретных частей. JSONB сохраняет названия исходных столбцов и null для неизвестных значений.';
CREATE INDEX ON refdata.reference_entry(record_kind);
CREATE SCHEMA registry_api;
COMMENT ON SCHEMA registry_api IS 'SAFE-ONLY synthetic model views for early Django integration. Does not enforce per-user unit access.';
CREATE VIEW registry_api.units AS SELECT unit_code, parent_code, short_name, full_name, level_name, country, confidence, personnel_own AS model_personnel_own, personnel_own_estimated AS model_personnel_estimated, sort_order, 'synthetic_model'::text AS data_status FROM mil_core.unit;
CREATE VIEW registry_api.staff_positions AS SELECT s.staff_id, s.unit_code, s.seq, s.position_name, s.rank_name, (s.person_id IS NOT NULL) AS has_model_person_link, 'synthetic_model'::text AS data_status FROM mil_core.staff_position s;
CREATE VIEW registry_api.unit_staff_summary AS SELECT u.unit_code, count(s.staff_id) AS direct_model_staff_positions, count(s.staff_id) FILTER (WHERE s.person_id IS NOT NULL) AS direct_model_person_links, 'synthetic_model'::text AS data_status FROM mil_core.unit u LEFT JOIN mil_core.staff_position s ON s.unit_code = u.unit_code GROUP BY u.unit_code;
CREATE VIEW registry_api.items AS SELECT item_sname, item_name, category, country AS manufacturer_country, unit_measure, 'synthetic_or_reference_catalog'::text AS data_status FROM mil_core.item;
CREATE VIEW registry_api.holdings AS SELECT h.unit_code, h.item_sname, h.qty AS model_qty, h.derived_from, 'synthetic_model_not_actual_inventory'::text AS data_status FROM mil_core.holding h;
CREATE VIEW registry_api.sources AS SELECT source_code,source_name,publisher,url,source_type,license,accessed_on FROM mil_core.source;
COMMENT ON VIEW registry_api.unit_staff_summary IS 'Counts rows of modeled positions, not legal personnel, presence, vacancies or confirmed actual appointments.';
